-- Exam consent text version 2: the whole exam is now recorded (camera with
-- sound, and the screen when it is shared). Written as the next version only
-- for organisations whose newest LANGUAGE_EXAM text is still the unedited
-- built-in version 1 (src/db/consent-text.ts, CONSENT_V1_*); a text a school
-- wrote itself is left alone. Invitations already accepted keep their version.
-- Idempotent: once version 2 is the newest, version 1 no longer matches.
INSERT INTO "consent_texts" ("org_id", "solution", "version", "body")
SELECT c."org_id", c."solution", c."version" + 1, jsonb_build_object(
  'tr', 'Bu sınav Almanca seviyenizi ölçmek içindir. Sınav boyunca kameranız ve mikrofonunuz açık kalır, ekranınızın tamamı paylaşılır ve sınav tam ekranda yapılır. Sınavın tamamı kaydedilir: kameranızın görüntüsü ve sesi, ekranınız paylaşılıyorsa ekranınız da. Bu kaydı yalnızca okulunuzun yetkili kullanıcıları izleyebilir. Pencere veya sekme değiştirme, kopyala-yapıştır denemeleri ve benzeri olaylar kaydedilir. Belirli aralıklarla ve şüpheli anlarda kameranızdan ve ekranınızdan kareler alınır; bu kareler yapay zekâ ile ikinci kez kontrol edilebilir. Yapay zekâ yalnızca görülen olguları not eder (kaç kişi var, bir cihaz görünüyor mu gibi), duygu veya kişilik çıkarımı yapmaz. Hiçbir işaret sizi otomatik olarak başarısız saymaz: hepsini öğretmeniniz inceler. Yazma ve konuşma cevaplarınız için yapay zekâ bir seviye önerir, nihai kararı öğretmeniniz verir. Kayıtlar okulun belirlediği süre boyunca saklanır ve sonra silinir. Verilerinizle ilgili taleplerinizi bu sayfadaki bağlantıdan iletebilirsiniz.',
  'en', 'This exam measures your German. During the exam your camera and microphone stay on, your whole screen is shared and the exam runs in full screen. The whole exam is recorded: the picture and sound from your camera, and your screen when it is shared. Only authorised staff of your school can watch this recording. Switching windows or tabs, copy and paste attempts and similar events are recorded. Frames from your camera and screen are taken at intervals and at suspicious moments; these frames may be checked a second time by AI. The AI only notes what can be seen (how many people, whether a device is visible), never emotions or personality. No flag fails you automatically: your teacher reviews all of them. For your writing and speaking answers the AI suggests a level; your teacher makes the final decision. Recordings are kept for the period your school sets and then deleted. You can send requests about your data from the link on this page.'
)
FROM "consent_texts" c
WHERE c."solution" = 'LANGUAGE_EXAM'
  AND c."version" = (
    SELECT max(x."version") FROM "consent_texts" x
    WHERE x."org_id" = c."org_id" AND x."solution" = c."solution"
  )
  AND c."body"->>'tr' = 'Bu sınav Almanca seviyenizi ölçmek içindir. Sınav boyunca kameranız ve mikrofonunuz açık kalır, ekranınızın tamamı paylaşılır ve sınav tam ekranda yapılır. Pencere veya sekme değiştirme, kopyala-yapıştır denemeleri ve benzeri olaylar kaydedilir. Belirli aralıklarla ve şüpheli anlarda kameranızdan ve ekranınızdan kareler alınır; bu kareler yapay zekâ ile ikinci kez kontrol edilebilir. Yapay zekâ yalnızca görülen olguları not eder (kaç kişi var, bir cihaz görünüyor mu gibi), duygu veya kişilik çıkarımı yapmaz. Hiçbir işaret sizi otomatik olarak başarısız saymaz: hepsini öğretmeniniz inceler. Yazma ve konuşma cevaplarınız için yapay zekâ bir seviye önerir, nihai kararı öğretmeniniz verir. Kayıtlar okulun belirlediği süre boyunca saklanır ve sonra silinir. Verilerinizle ilgili taleplerinizi bu sayfadaki bağlantıdan iletebilirsiniz.'
  AND c."body"->>'en' = 'This exam measures your German. During the exam your camera and microphone stay on, your whole screen is shared and the exam runs in full screen. Switching windows or tabs, copy and paste attempts and similar events are recorded. Frames from your camera and screen are taken at intervals and at suspicious moments; these frames may be checked a second time by AI. The AI only notes what can be seen (how many people, whether a device is visible), never emotions or personality. No flag fails you automatically: your teacher reviews all of them. For your writing and speaking answers the AI suggests a level; your teacher makes the final decision. Recordings are kept for the period your school sets and then deleted. You can send requests about your data from the link on this page.';
